   114	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
   115	        // Empty out errors when we're saving a new waypoint as this indicates the user is updating their input
   116	        errorFields: {
   117	            route: null,
   118	        },
   119	
   120	        // Clear the existing route so that we don't show an old route
   121	        routes: {
   122	            route0: {
