   139	    // If current location is used, we would want to avoid saving it as a recent waypoint. This prevents the 'Your Location'
   140	    // text from showing up in the address search suggestions
   141	    if (deepEqual(waypoint?.address, CONST.YOUR_LOCATION_TEXT)) {
