   245	/**
   246	 * Returns the Onyx data that is used for both the OpenApp and ReconnectApp API commands.
   247	 */
   248	function getOnyxDataForOpenOrReconnect(
   249	    isOpenApp = false,
   250	    isFullReconnect = false,
   251	    shouldKeepPublicRooms = false,
   252	    allReportsWithDraftComments?: Record<string, string | undefined>,
   253	): OnyxData {
   254	    const result: OnyxData = {
   255	        optimisticData: [
   256	            {
   257	                onyxMethod: Onyx.METHOD.MERGE,
   258	                key: ONYXKEYS.IS_LOADING_REPORT_DATA,
   259	                value: true,
   260	            },
   261	        ],
   262	        successData: [],
   263	        finallyData: [
   264	            {
   265	                onyxMethod: Onyx.METHOD.MERGE,
   266	                key: ONYXKEYS.IS_LOADING_REPORT_DATA,
   267	                value: false,
   268	            },
   269	        ],
   270	        queueFlushedData: [
   271	            {
   272	                onyxMethod: Onyx.METHOD.MERGE,
   273	                key: ONYXKEYS.HAS_LOADED_APP,
   274	                value: true,
   275	            },
   276	        ],
   277	    };
   278	
   279	    if (isOpenApp) {
   280	        result.optimisticData?.push({
   281	            onyxMethod: Onyx.METHOD.MERGE,
   282	            key: ONYXKEYS.IS_LOADING_APP,
   283	            value: true,
   284	        });
   285	
   286	        result.finallyData?.push({
   287	            onyxMethod: Onyx.METHOD.MERGE,
   288	            key: ONYXKEYS.IS_LOADING_APP,
   289	            value: false,
   290	        });
   291	    }
   292	
   293	    if (isOpenApp || isFullReconnect) {
   294	        result.successData?.push({
   295	            onyxMethod: Onyx.METHOD.MERGE,
   296	            key: ONYXKEYS.LAST_FULL_RECONNECT_TIME,
   297	            value: DateUtils.getDBTime(),
   298	        });
   299	    }
   300	
   301	    if (shouldKeepPublicRooms) {
   302	        const publicReports = Object.values(allReports ?? {}).filter((report) => isPublicRoom(report) && isValidReport(report));
   303	        publicReports?.forEach((report) => {
   304	            result.successData?.push({
   305	                onyxMethod: Onyx.METHOD.MERGE,
   306	                key: `${ONYXKEYS.COLLECTION.REPORT}${report?.reportID}`,
   307	                value: {
   308	                    ...report,
   309	                },
   310	            });
   311	        });
   312	    }
   313	
   314	    // Find all reports that have a non-null draft comment and map them to their corresponding report objects from allReports
   315	    // This ensures that any report with a draft comment is preserved in Onyx even if it doesn’t contain chat history
   316	    const reportsWithDraftComments = Object.entries(allReportsWithDraftComments ?? {})
   317	        .filter(([, value]) => value !== null)
   318	        .map(([key]) => key.replace(ONYXKEYS.COLLECTION.REPORT_DRAFT_COMMENT, ''))
   319	        .map((reportID) => allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`]);
   320	
   321	    reportsWithDraftComments?.forEach((report) => {
   322	        result.successData?.push({
   323	            onyxMethod: Onyx.METHOD.MERGE,
   324	            key: `${ONYXKEYS.COLLECTION.REPORT}${report?.reportID}`,
   325	            value: {
   326	                ...report,
   327	            },
   328	        });
   329	    });
   330	
   331	    return result;
   332	}
