   313	function hasActiveChatEnabledPolicies(policies: Array<OnyxEntry<PolicySelector>> | OnyxCollection<PolicySelector>, includeOnlyAdminPolicies = false): boolean {
   314	    const chatEnabledPolicies = Object.values(policies ?? {}).filter(
   315	        (policy) => policy?.isPolicyExpenseChatEnabled && (!includeOnlyAdminPolicies || policy.role === CONST.POLICY.ROLE.ADMIN),
   316	    );
   317	
   318	    if (chatEnabledPolicies.length === 0) {
   319	        return false;
   320	    }
   321	
   322	    if (chatEnabledPolicies.some((policy) => !policy?.pendingAction)) {
   323	        return true;
   324	    }
   325	
   326	    if (chatEnabledPolicies.some((policy) => policy?.pendingAction === CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD)) {
   327	        return true;
