   329	
   330	    if (chatEnabledPolicies.some((policy) => policy?.pendingAction === CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE)) {
   331	        return false;
   332	    }
   333	
   334	    // If there are no add or delete pending actions the only option left is an update
   335	    // pendingAction, in which case we should return true.
   336	    return true;
